+const WRITE_TOOLS: ReadonlySet<string> = new Set([
+	"editor",
+	"write_to_file",
+	"replace_in_file",
+	"apply_patch",
+]);
+
+const TITLE = "Next";
+const COMMAND = "next";
+const SET_SIZE = 3;
