+	kind: string;
+	tone: ComposerSuggestionItem["tone"];
+	icon: ComposerSuggestionItem["icon"];
+	label: string;
+	prompt: string;
+	why: string;
+};
+
+/** Every row the rules can stand behind for this turn, best first. */
+export function pool(facts: Facts): Row[] {
+	const rows: Row[] = [];
+	if (facts.status === "cancelled")
