+			kind: "continue",
+			tone: "continue",
+			icon: "resume",
+			label: "Resume",
+			prompt: "Pick up the work the stopped turn left unfinished.",
+			why: "The last turn was stopped before it finished.",
+		});
+	if (facts.status === "failed")
