+		const arg = args[index]?.trim() ?? "";
+		if (arg === "--skill" || arg === "-s") {
+			skill = args[index + 1]?.trim();
+			index++;
+			continue;
+		}
+		if (arg.startsWith("--skill=")) {
+			skill = arg.slice("--skill=".length).trim();
+			continue;
+		}
+		if (arg.startsWith("-") || sourceArg !== undefined) {
