+	let end = dashed.length;
+	while (start < end && (dashed[start] === "." || dashed[start] === "-")) {
+		start++;
+	}
+	while (end > start && (dashed[end - 1] === "." || dashed[end - 1] === "-")) {
+		end--;
+	}
