+	const name = sanitizeSkillInstallName(skillName);
+	const accepted = (acceptedNames ?? []).map(sanitizeSkillInstallName);
+	return accepted.length === 0 || accepted.includes(name)
+		? name
+		: (accepted[0] ?? name);

